import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百六十九章 投生到痛苦的地方","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/169第一百六十九章 投生到痛苦的地方.md","filePath":"meditation/巴利文大藏经/169第一百六十九章 投生到痛苦的地方.md"}'),o={name:"meditation/巴利文大藏经/169第一百六十九章 投生到痛苦的地方.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第一百六十九章-投生到痛苦的地方" tabindex="-1">第一百六十九章 投生到痛苦的地方 <a class="header-anchor" href="#第一百六十九章-投生到痛苦的地方" aria-label="Permalink to &quot;第一百六十九章 投生到痛苦的地方&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部17相应10经/有偈颂的经(利得恭敬相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望，这些是让人内心颤抖恐怖的，这些是让人内心激烈搅动的，这些是让人内心暴躁不安的，这些是修行人内心达到清净安稳的障碍，这些是修行人内心挣脱束缚捆绑的阻碍。</p><p>弟子们，这些贪求世间人丰厚的供养，贪求富贵舒适的生活，贪求世间人虔诚的尊敬、恭敬，贪求家喻户晓的名誉声望的修行人、出家人，他们获得丰厚供养、舒适生活、虔诚恭敬、广大名声的时候，就会被他们内心生起的快乐、喜悦所谋害；他们无法获得丰厚供养、舒适生活、虔诚恭敬、广大名声的时候，就会被他们内心生起的悲伤、忧愁所谋害；他们得到粗劣的供养，过着困苦的生活，被人轻视怠慢，不为人知或者名声很小的时候，就会被他们内心生起的哀愁、忧虑所谋害。这些贪求世间人丰厚的供养，贪求富贵舒适的生活，贪求世间人虔诚的尊敬、恭敬，贪求家喻户晓的名誉声望的修行人、出家人，这些因为供养的优劣，生活的舒适、困苦，世间人的恭敬、轻视，名声的广大、微小而胡思乱想的修行人、出家人，他们死后将会投生到痛苦的地方，将会投生到不幸的地方，将会投生到受苦的地方，将会投生到地狱、饿鬼、畜生三恶道受苦。</p><p>弟子们，世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望就是这样的让人内心颤抖恐怖，就是这样的让人内心激烈搅动，就是这样的让人内心暴躁不安。</p><p>世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望是修行人内心达到清净安稳的障碍，是修行人内心挣脱束缚捆绑的阻碍。弟子们，因此，你们应该这样去修行：「我们要舍离、放弃已经获得的丰厚供养，我们要舍离、放弃已经获得的富贵舒适的生活，我们要舍离、放弃已经获得的世间人虔诚的尊敬、恭敬，我们要舍离、放弃已经获得的家喻户晓的名誉声望。而且我们不要执着和挂念这些已经获得的丰厚供养，不要执着和挂念这些已经获得的富贵舒适的生活，不要执着和挂念这些已经获得的世间人虔诚的尊敬、恭敬，不要执着和挂念这些已经获得的家喻户晓的名誉声望。我们不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望扰乱我们的内心；不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望让我们胡思乱想、内心散乱。」弟子们，你们就应该这样的去修行。</p><p>弟子们，不管世间人供养也好，不供养也罢，内心都不会因此而扰动、困惑，都不会由此产生喜怒哀乐等等无数的念想，这样的人他们才是真正修行的人，这样的人他们才是内心清净的人。</p><p>不管过的是富贵的生活，还是过的是困苦的生活，内心都不会因此的而扰动、困惑，都不会由此产生喜怒哀乐等等无数的念想，这样的人他们才是真正修行的人，这样的人他们才是内心清净的人。</p><p>不管世间人恭敬也好，不恭敬也罢，内心都不会因此而扰动、困惑，都不会由此产生喜怒哀乐等等无数的念想，这样的人他们才是真正修行的人，这样的人他们才是内心清净的人。</p><p>不管名声广大，还是不为人知或者名声微小，内心都不会因此而扰动、困惑，都不会由此产生喜怒哀乐等等无数的念想，这样的人他们才是真正修行的人，这样的人他们才是内心清净的人。</p><p>他们是精进的修行人，不管遇见外界任何的事物事情，他们都能将自己的内心集中到清净的境界之中，他们不会胡思乱想，他们的内心不会散乱。他们善于熄灭、除灭自己喜怒哀乐等等的念想，他们善于熄灭、除灭自己内心的一切念想，他们修行的这个法就是解脱之法，他们能够除灭世间一切事物的束缚捆绑，他们能够除灭自己一切的烦恼和痛苦，他们能够从生死轮回中解脱出来，他们能够最终证悟达到不生不灭涅槃的境界。”</p><p>这时，佛陀说偈言：</p><p>「受供养之时，</p><p>不受供养时，</p><p>二者不扰定。</p><p>恭敬及名声，</p><p>富贵及困苦，</p><p>亦不动本心。</p><p>精勤入定者，</p><p>清净无苦恼。</p><p>长于灭取者，</p><p>此法谓解脱。</p><p>生死烦恼尽，</p><p>直达涅槃境。」</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',26)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
